/* WEMS offline chart engine: lightweight Canvas bar chart compatible with the dashboard's Chart constructor. */
(function(){function Chart(canvas,config){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.config=config||{};this.resize();window.addEventListener('resize',this.resize.bind(this));this.draw()}Chart.prototype.resize=function(){var r=this.canvas.getBoundingClientRect();this.canvas.width=Math.max(300,Math.floor(r.width||600));this.canvas.height=Math.max(220,Math.floor(r.height||300));this.draw&&this.draw()};Chart.prototype.draw=function(){var c=this.ctx,d=this.config.data||{},sets=d.datasets||[],labels=d.labels||[],w=this.canvas.width,h=this.canvas.height;c.clearRect(0,0,w,h);var pad={l:55,r:20,t:25,b:45},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b,max=0;sets.forEach(function(s){(s.data||[]).forEach(function(v){max=Math.max(max,Number(v)||0)})});max=max||1;c.strokeStyle='#dfe5e9';c.fillStyle='#555';c.lineWidth=1;c.font='12px Segoe UI,Arial';for(var i=0;i<=4;i++){var y=pad.t+ph-(ph*i/4);c.beginPath();c.moveTo(pad.l,y);c.lineTo(w-pad.r,y);c.stroke();c.fillText(Math.round(max*i/4).toLocaleString(),8,y+4)}var n=labels.length||1,group=pw/n,bar=Math.max(6,Math.min(28,group/(sets.length+1)));sets.forEach(function(s,si){c.fillStyle=s.backgroundColor||'#3498db';(s.data||[]).forEach(function(v,i){var x=pad.l+i*group+(group-(sets.length*bar))/2+si*bar,y=pad.t+ph-(Number(v)||0)/max*ph;c.fillRect(x,y,bar-2,pad.t+ph-y)})});c.fillStyle='#555';c.textAlign='center';labels.forEach(function(l,i){c.fillText(String(l),pad.l+i*group+group/2,h-18)});c.textAlign='start';};window.Chart=Chart})();
